            "void", EnumSet.of(Role.CLERK, Role.STEWARD), "close", EnumSet.of(Role.CLERK, Role.STEWARD),
            "reassign", EnumSet.of(Role.STEWARD), "reopen", EnumSet.of(Role.STEWARD));

