127	    /** The sheet's dated settings as they stood at the end of a date: every value recorded while the
128	     *  sheet's today was on or before it counts, every later one does not. */
129	    @Transactional(readOnly = true)
130	    public DatedSettings datedAsOf(String sheetId, LocalDate asOf) {
131	        Map<String, Map<LocalDate, String>> byKey = new TreeMap<>();
132	        for (SettingChange change : changes.findBySheetIdOrderByIdAsc(sheetId)) {
133	            if (change.madeBy(asOf)) {
134	                byKey.computeIfAbsent(change.getKey(), k -> new TreeMap<>()).put(change.getFrom(), change.getValue());
135	            }
136	        }
137	        List<SheetSettingDated> then = new ArrayList<>();
138	        byKey.forEach((key, values) -> values.forEach((from, value) ->
139	                then.add(new SheetSettingDated(sheetId, key, from, value))));
140	        return DatedSettings.of(then);
141	    }
