224	    /** Record a dated setting's value (blank: cleared) from a date, or from the sheet's today when none is
225	     *  given; a value already recorded from that date is replaced. The audit line carries the from-date
226	     *  when one was given. */
227	    private void record(String sheetId, String user, String key, String value, LocalDate from) {
228	        sheets.load(sheetId);
229	        LocalDate on = from != null ? from : sheets.today(sheetId);
230	        SheetSettingDated setting = dated.findBySheetIdAndKeyAndFrom(sheetId, key, on).orElse(null);
231	        try {
232	            if (setting == null) {
233	                dated.saveAndFlush(new SheetSettingDated(sheetId, key, on, value));
234	            } else {
235	                setting.setValue(value);
236	                dated.saveAndFlush(setting);
237	            }
238	        } catch (DataIntegrityViolationException raced) {
239	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The setting was changed by someone else.");
240	        }
241	        changes.saveAndFlush(new SettingChange(sheetId, key, on, value, sheets.today(sheetId)));
242	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + key
243	                + " value=" + value + (from == null ? "" : " from=" + from));
244	    }
