533	    /** The roles a comma separated list names; refused when one of them is not a role. */
534	    private static Set<Role> rolesOf(String value) {
535	        Set<Role> roles = EnumSet.noneOf(Role.class);
536	        for (String label : value.split(",")) {
537	            roles.add(Role.of(label.trim()).orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
538	                    "Name the roles as a comma separated list of clerk and steward.")));
539	        }
540	        return roles;
541	    }
