549	        }
550	        String value = roles == null || roles.isBlank() ? ""
551	                : String.join(",", Arrays.stream(roles.split(",")).map(String::trim).toList());
552	        if (!value.isEmpty()) rolesOf(value);
553	        sheets.load(sheetId);
554	        String key = permissionKey(action);
555	        SheetSetting setting = settings.findBySheetIdAndKey(sheetId, key).orElse(null);
556	        try {
557	            if (value.isEmpty()) {
558	                if (setting != null) {
559	                    settings.delete(setting);
560	                    settings.flush();
561	                }
562	            } else if (setting == null) {
563	                settings.saveAndFlush(new SheetSetting(sheetId, key, value));
564	            } else {
565	                setting.setValue(value);
566	                settings.saveAndFlush(setting);
567	            }
568	        } catch (DataIntegrityViolationException raced) {
569	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The setting was changed by someone else.");
570	        }
571	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + key + " value=" + value);
572	        return value;
573	    }
574	
575	    /** The roles the sheet has assigned, by user name; any other name is a clerk. */
576	    @Transactional(readOnly = true)
577	    public List<SheetRole> roles(String sheetId) {
578	        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
579	    }
580	
581	    /** The role the user name acts in on the sheet: a steward while a delegation to it covers the
582	     *  sheet's today, otherwise the one it was assigned (a clerk unless it was assigned another). */
583	    @Transactional(readOnly = true)
584	    public Role roleOf(String sheetId, String user) {
585	        return delegationOn(sheetId, user).isPresent() ? Role.STEWARD : assignedRoleOf(sheetId, user);
586	    }
587	
588	    /** The role the sheet assigned a user name, leaving out any delegation: a clerk unless assigned another. */
589	    @Transactional(readOnly = true)
590	    public Role assignedRoleOf(String sheetId, String user) {
591	        return roles.findBySheetIdAndUserName(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
592	    }
593	
594	    /** The steward the user acts for while a delegation to it covers the sheet's today; the latest
595	     *  made when more than one does. */
596	    @Override
597	    @Transactional(readOnly = true)
598	    public Optional<String> actingFor(String sheetId, String user) {
599	        return delegationOn(sheetId, user).map(Delegation::getDelegatedBy);
600	    }
601	
602	    private Optional<Delegation> delegationOn(String sheetId, String user) {
603	        List<Delegation> made = delegations.findBySheetIdAndUserNameOrderByIdDesc(sheetId, user);
604	        if (made.isEmpty()) return Optional.empty();
605	        LocalDate today = sheets.today(sheetId);
606	        return made.stream().filter((d) -> d.covers(today)).findFirst();
607	    }
608	
609	    /** The sheet's delegations in the order they were made. */
610	    @Transactional(readOnly = true)
611	    public List<Delegation> delegations(String sheetId) {
612	        return delegations.findBySheetIdOrderByIdAsc(sheetId);
613	    }
614	
615	    /** Delegate the steward role to a user name from a date to a date, inclusive (blank from: the
616	     *  sheet's today); refused to anyone the sheet did not assign the steward role, and when the
617	     *  to-date is before the from-date. */
618	    @Transactional
619	    public Delegation delegate(String sheetId, String user, String userName, LocalDate from, LocalDate to) {
620	        sheets.load(sheetId);
621	        if (assignedRoleOf(sheetId, user) != Role.STEWARD) {
622	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can delegate the steward role.");
623	        }
624	        LocalDate start = from != null ? from : sheets.today(sheetId);
625	        LocalDate end = to != null ? to : start;
626	        if (end.isBefore(start)) {
627	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date is before the from-date.");
628	        }
629	        Delegation saved = delegations.saveAndFlush(new Delegation(sheetId, userName, start, end, user));
630	        audit.recordOnCommit("DELEGATED sheet=" + sheetId + " by=" + user + " user=" + userName + " from=" + start
631	                + " to=" + end);
632	        return saved;
633	    }
634	
635	    /** Assign a user name a role on the sheet, replacing the one it had. */
636	    @Transactional
637	    public SheetRole setRole(String sheetId, String user, String userName, Role role) {
638	        sheets.load(sheetId);
639	        SheetRole assigned = roles.findBySheetIdAndUserName(sheetId, userName).orElse(null);
640	        if (assigned == null) {
641	            assigned = new SheetRole(sheetId, userName, role);
642	        } else {
643	            assigned.setRole(role);
644	        }
645	        SheetRole saved;
646	        try {
647	            saved = roles.saveAndFlush(assigned);
648	        } catch (DataIntegrityViolationException raced) {
649	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The role was changed by someone else.");
650	        }
651	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + userName
652	                + " role=" + role.label());
653	        return saved;
654	    }
655	}
