package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Grade;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class RateService {

    private final RateRepository rates;
    private final RateChangeRepository changes;
    private final SheetService sheets;
    private final Rollup rollup;
    private final Audit audit;

    public RateService(RateRepository rates, RateChangeRepository changes, SheetService sheets, Rollup rollup,
            Audit audit) {
        this.rates = rates;
        this.changes = changes;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The sheet's rates in grade order, then by from-date; a grade with no rate is left out. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdInOrder(sheetId);
    }

    /** The grade's rate in force on a date: the one with the latest from-date on or before it, or
     *  null when the date is before every rate the grade has or after that rate's to-date. */
    @Transactional(readOnly = true)
    public Rate inForce(String sheetId, Grade grade, LocalDate date) {
        return Rate.inForce(rates.findForGrade(sheetId, grade), date);
    }

    /** The grade's rate in force on a date as the sheet's rates stood at the end of another date (asOf):
     *  every setting made while the sheet's today was on or before it counts, every later one does not;
     *  null when none is in force then. */
    @Transactional(readOnly = true)
    public Rate inForceAsOf(String sheetId, Grade grade, LocalDate date, LocalDate asOf) {
        Map<LocalDate, Rate> byFrom = new HashMap<>();
        Rate fromStart = null;
        for (RateChange change : changes.findBySheetIdOrderByIdAsc(sheetId)) {
            if (change.getGrade() != grade || !change.madeBy(asOf)) continue;
            if (change.getFrom() == null) fromStart = change.toRate();
            else byFrom.put(change.getFrom(), change.toRate());
        }
        List<Rate> gradeRates = new ArrayList<>();
        if (fromStart != null) gradeRates.add(fromStart);
        byFrom.keySet().stream().sorted().forEach((from) -> gradeRates.add(byFrom.get(from)));
        return Rate.inForce(gradeRates, date);
    }

    /** Set the sheet's rate for a grade from a from-date (none: from the beginning of time) through
     *  a to-date (none: until the grade's next rate), replacing the rate it had for that from-date. A
     *  to-date before the from-date is refused. */
    @Transactional
    public Rate set(String sheetId, String user, Grade grade, LocalDate from, LocalDate to, BigDecimal pct) {
        if (from != null && to != null && to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date is before the from-date.");
        }
        sheets.load(sheetId);
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        Rate rate = (from == null ? rates.findFromStart(sheetId, grade) : rates.findFrom(sheetId, grade, from))
                .orElse(null);
        if (rate == null) {
            rate = new Rate(sheetId, grade, from, to, pct);
        } else {
            rate.setPct(pct);
            rate.setTo(to);
        }
        Rate saved;
        try {
            saved = rates.saveAndFlush(rate);
            changes.saveAndFlush(new RateChange(saved, sheets.today(sheetId)));
        } catch (DataIntegrityViolationException raced) {
            // Another user set the same grade's rate for that from-date at the same moment.
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The rate was changed by someone else.");
        }
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + saved.getGrade()
                + " rate=" + saved.getPct().toPlainString() + (from == null ? "" : " from=" + from)
                + (to == null ? "" : " to=" + to));
        rollup.recordChanges(user, before);
        return saved;
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.person.Grade;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface RateRepository extends JpaRepository<Rate, Long> {

    /** The sheet's rates in grade order, each grade's from the beginning of time first, then by from-date. */
    @Query("select r from Rate r where r.sheetId = :sheetId order by r.grade asc, r.from asc nulls first")
    List<Rate> findBySheetIdInOrder(@Param("sheetId") String sheetId);

    /** The grade's rates, with the one with no from-date first, then by from-date. */
    @Query("select r from Rate r where r.sheetId = :sheetId and r.grade = :grade order by r.from asc nulls first")
    List<Rate> findForGrade(@Param("sheetId") String sheetId, @Param("grade") Grade grade);

    /** The grade's rate with no from-date. */
    @Query("select r from Rate r where r.sheetId = :sheetId and r.grade = :grade and r.from is null")
    Optional<Rate> findFromStart(@Param("sheetId") String sheetId, @Param("grade") Grade grade);

    /** The grade's rate with this from-date. */
    @Query("select r from Rate r where r.sheetId = :sheetId and r.grade = :grade and r.from = :from")
    Optional<Rate> findFrom(@Param("sheetId") String sheetId, @Param("grade") Grade grade,
            @Param("from") LocalDate from);
}
package net.officefloor.hq.app.sheet;

import java.time.Instant;
import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class SheetService {

    private final SheetRepository sheets;
    private final Rollup rollup;
    private final ApplicationEventPublisher events;
    private final Audit audit;
    // The settings read the sheet's today, so they are looked up when needed rather than injected.
    private final ObjectProvider<SettingService> settings;

    public SheetService(SheetRepository sheets, Rollup rollup, ApplicationEventPublisher events, Audit audit,
            ObjectProvider<SettingService> settings) {
        this.sheets = sheets;
        this.rollup = rollup;
        this.events = events;
        this.audit = audit;
        this.settings = settings;
    }

    /** The sheet with this id, as the store holds it now; a sheet never loaded before starts empty. */
    @Transactional
    public Sheet load(String id) {
        return sheets.findById(id).orElseGet(() -> create(id));
    }

    /**
     * The sheet's today. Every decision that depends on the date, and every default date, uses this
     * and never the real clock.
     */
    @Transactional
    public LocalDate today(String id) {
        return load(id).getToday();
    }

    /** Change the sheet's today; it has no audit line of its own: first a snapshot of each person's
     *  due-total on the day being left, then what it sets off (such as the periods it closes) and then
     *  the figures it moves. */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = load(id);
        Rollup.Snapshot before = rollup.snapshot(id);
        rollup.recordSnapshot(user, before);
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        events.publishEvent(new TodayChanged(id, user, today));
        rollup.recordChanges(user, before);
        return saved;
    }

    /** Archive the sheet: it stays visible, and every change on it is refused from then on (see
     *  {@code ArchiveGuard}). Refused to anyone but a steward of the sheet, and when it is archived. */
    @Transactional
    public Sheet archive(String id, String user) {
        load(id);
        Sheet sheet = sheets.findForUpdate(id).orElseThrow();
        if (settings.getObject().roleOf(id, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can archive the sheet.");
        }
        if (sheet.isArchived()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is already archived.");
        }
        sheet.archive();
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SHEET_ARCHIVED sheet=" + id + " by=" + user);
        return saved;
    }

    /**
     * The sheet's next claim number: 1 for its first opened claim, then 2, and so on. The sheet stays
     * locked until the transaction ends, so two claims opened at once never share a number.
     */
    @Transactional
    public int nextClaimNumber(String id) {
        load(id);
        sheets.takeClaimNumber(id);
        return sheets.claimNumbersUsed(id);
    }

    /**
     * The sheet's next settle batch number: 1 for its first bulk settle that settled a claim, then 2,
     * and so on. The sheet stays locked until the transaction ends, so two batches never share a number.
     */
    @Transactional
    public int nextSettleBatch(String id) {
        load(id);
        sheets.takeSettleBatch(id);
        return sheets.settleBatchesUsed(id);
    }

    /**
     * The next number of one of the sheet's per-period sequences (by key): 1 for its first, then 2,
     * and so on. The sheet stays locked until the transaction ends, so two claims opened at once
     * never share a number.
     */
    @Transactional
    public int nextSequenceNumber(String id, String key) {
        load(id);
        sheets.findForUpdate(id);
        Integer used = sheets.sequenceNumbersUsed(id, key);
        if (used == null) {
            sheets.startSequence(id, key);
            return 1;
        }
        sheets.takeSequenceNumber(id, key);
        return used + 1;
    }

    private Sheet create(String id) {
        try {
            // The only use of the real clock: a new sheet's today starts as the real date.
            return sheets.saveAndFlush(new Sheet(id, Instant.now(), LocalDate.now()));
        } catch (DataIntegrityViolationException raced) {
            // Another user loaded the same new id at the same moment.
            return sheets.findById(id).orElseThrow(() -> raced);
        }
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.LockModeType;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface SheetRepository extends JpaRepository<Sheet, String> {

    /** Count one more claim number given out; the sheet's row stays locked until the transaction ends. */
    @Modifying(flushAutomatically = true)
    @Query("update Sheet s set s.claimNumbersUsed = s.claimNumbersUsed + 1 where s.id = :id")
    int takeClaimNumber(@Param("id") String id);

    /** How many claim numbers the sheet has given out. */
    @Query("select s.claimNumbersUsed from Sheet s where s.id = :id")
    int claimNumbersUsed(@Param("id") String id);

    /** Count one more settle batch; the sheet's row stays locked until the transaction ends. */
    @Modifying(flushAutomatically = true)
    @Query("update Sheet s set s.settleBatchesUsed = s.settleBatchesUsed + 1 where s.id = :id")
    int takeSettleBatch(@Param("id") String id);

    /** How many settle batches the sheet has had. */
    @Query("select s.settleBatchesUsed from Sheet s where s.id = :id")
    int settleBatchesUsed(@Param("id") String id);

    /** How many numbers one of the sheet's per-period sequences has given out; null when none. */
    @Query(value = "select used from claim_number_sequence where sheet_id = :id and sequence_key = :key",
            nativeQuery = true)
    Integer sequenceNumbersUsed(@Param("id") String id, @Param("key") String key);

    /** Start one of the sheet's per-period sequences, its first number given out. */
    @Modifying(flushAutomatically = true)
    @Query(value = "insert into claim_number_sequence (sheet_id, sequence_key, used) values (:id, :key, 1)",
            nativeQuery = true)
    int startSequence(@Param("id") String id, @Param("key") String key);

    /** Count one more number given out by one of the sheet's per-period sequences. */
    @Modifying(flushAutomatically = true)
    @Query(value = "update claim_number_sequence set used = used + 1 where sheet_id = :id and sequence_key = :key",
            nativeQuery = true)
    int takeSequenceNumber(@Param("id") String id, @Param("key") String key);

    /** The sheet, locked until the transaction ends, so changes that check the sheet as a whole
     *  (such as periods not overlapping) are made one after the other. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select s from Sheet s where s.id = :id")
    Optional<Sheet> findForUpdate(@Param("id") String id);

    /** Whether the sheet is archived; false for a sheet never loaded. */
    @Query("select count(s) > 0 from Sheet s where s.id = :id and s.archived = true")
    boolean isArchived(@Param("id") String id);
}

