372	  protected async saveSettings(): Promise<void> {
373	    // A second submit before the first has answered is ignored, so it stores one change, not two.
374	    if (this.savingSettings()) return;
375	    const sheet = this.session.sheet();
376	    if (!sheet) return;
377	    this.settingsError.set('');
378	    const { clerkLimit, clerkLimitFrom, floor, floorFrom, terms, termsFrom, latePct, latePctFrom, policyDate,
379	      periodNumberingFrom, cap, capFrom, proofThreshold, proofThresholdFrom,
380	      noteThreshold, noteThresholdFrom, graceDays, entryDate, pot } = this.settingsForm.controls;
381	    // A dated setting is saved when its value or its from-date was changed; the from-date checked first.
382	    const froms = [
383	      { label: 'clerk limit', control: clerkLimitFrom }, { label: 'floor', control: floorFrom },
384	      { label: 'terms', control: termsFrom }, { label: 'late percent', control: latePctFrom },
385	      { label: 'cap', control: capFrom }, { label: 'proof threshold', control: proofThresholdFrom },
386	      { label: 'note threshold', control: noteThresholdFrom },
387	      ...GRADES.map((g) => ({ label: `terms of grade ${g}`, control: this.gradeTermsFromForm.controls[g] })),
388	      ...GRADES.map((g) => ({ label: `grace of grade ${g}`, control: this.gradeGraceFromForm.controls[g] })),
389	      ...GRADES.map((g) => ({ label: `proof threshold of grade ${g}`, control: this.gradeProofThresholdFromForm.controls[g] })),
390	    ];
391	    for (const { label, control } of froms) {
392	      const from = control.value.trim();
393	      if (from !== '' && !isDate(from)) {
394	        this.settingsError.set(`Type the date the ${label} is from as yyyy-mm-dd, or leave it blank for the sheet's today.`);
395	        return;
396	      }
397	    }
398	    const fromOf = (control: AbstractControl<string>): string | null => control.value.trim() === '' ? null : control.value.trim();
399	    const dirty = (value: AbstractControl, from: AbstractControl): boolean => changed(value) || changed(from);
400	    const limit = clerkLimit.value.trim();
401	    const floorValue = floor.value.trim();
402	    const termsValue = terms.value.trim();
403	    const latePctValue = latePct.value.trim();
404	    const policyDateValue = policyDate.value.trim();
405	    const periodNumberingFromValue = periodNumberingFrom.value.trim();
406	    const capValue = cap.value.trim();
407	    const proofThresholdValue = proofThreshold.value.trim();
408	    const noteThresholdValue = noteThreshold.value.trim();
409	    const graceDaysValue = graceDays.value.trim();
410	    const entryDateValue = entryDate.value.trim();
411	    const potValue = pot.value.trim();
412	    if (dirty(clerkLimit, clerkLimitFrom) && limit !== '' && !MONEY.test(limit)) {
413	      this.settingsError.set('Type a clerk limit of 0.00 or more, with up to two decimals, or leave it blank.');
414	      return;
415	    }
416	    if (dirty(floor, floorFrom) && !MONEY.test(floorValue)) {
417	      this.settingsError.set('Type a floor of 0.00 or more, with up to two decimals.');
418	      return;
419	    }
420	    if (dirty(terms, termsFrom) && (!DAYS.test(termsValue) || Number(termsValue) > 36500)) {
421	      this.settingsError.set('Type terms as a whole number of business days, from 0 to 36500.');
422	      return;
423	    }
424	    const gradeTermsValues = GRADES.map((g) => ({ grade: g, control: this.gradeTermsForm.controls[g],
425	      from: this.gradeTermsFromForm.controls[g], value: this.gradeTermsForm.controls[g].value.trim() }));
426	    for (const { grade, control, from, value } of gradeTermsValues) {
427	      if (dirty(control, from) && value !== '' && (!DAYS.test(value) || Number(value) > 36500)) {
428	        this.settingsError.set(`Type the terms of grade ${grade} as a whole number of business days, from 0 to 36500, or leave them blank for the sheet's terms.`);
429	        return;
430	      }
431	    }
432	    const gradeGraceValues = GRADES.map((g) => ({ grade: g, control: this.gradeGraceForm.controls[g],
433	      from: this.gradeGraceFromForm.controls[g], value: this.gradeGraceForm.controls[g].value.trim() }));
434	    for (const { grade, control, from, value } of gradeGraceValues) {
435	      if (dirty(control, from) && value !== '' && (!DAYS.test(value) || Number(value) > 36500)) {
436	        this.settingsError.set(`Type the grace of grade ${grade} as a whole number of days, from 0 to 36500, or leave it blank for none.`);
437	        return;
438	      }
439	    }
440	    if (dirty(latePct, latePctFrom) && !PCT.test(latePctValue)) {
441	      this.settingsError.set('Type a late percent of 0.00 or more, with up to two decimals.');
442	      return;
443	    }
444	    if (changed(policyDate) && policyDateValue !== '' && !isDate(policyDateValue)) {
445	      this.settingsError.set('Type a policy date as yyyy-mm-dd, or leave it blank for the sheet\'s today.');
446	      return;
447	    }
448	    if (changed(periodNumberingFrom) && periodNumberingFromValue !== '' && !isDate(periodNumberingFromValue)) {
449	      this.settingsError.set('Type a period numbering date as yyyy-mm-dd, or leave it blank for sheet-wide numbering.');
450	      return;
451	    }
452	    if (dirty(cap, capFrom) && capValue !== '' && !MONEY.test(capValue)) {
453	      this.settingsError.set('Type a cap of 0.00 or more, with up to two decimals, or leave it blank for no cap.');
454	      return;
455	    }
456	    if (dirty(proofThreshold, proofThresholdFrom) && proofThresholdValue !== '' && !MONEY.test(proofThresholdValue)) {
457	      this.settingsError.set('Type a proof threshold of 0.00 or more, with up to two decimals, or leave it blank for none.');
458	      return;
459	    }
460	    const gradeProofThresholdValues = GRADES.map((g) => ({ grade: g, control: this.gradeProofThresholdForm.controls[g],
461	      from: this.gradeProofThresholdFromForm.controls[g], value: this.gradeProofThresholdForm.controls[g].value.trim() }));
462	    for (const { grade, control, from, value } of gradeProofThresholdValues) {
463	      if (dirty(control, from) && value !== '' && !MONEY.test(value)) {
464	        this.settingsError.set(`Type the proof threshold of grade ${grade} as 0.00 or more, with up to two decimals, or leave it blank for the sheet's.`);
465	        return;
466	      }
467	    }
468	    if (dirty(noteThreshold, noteThresholdFrom) && noteThresholdValue !== '' && !MONEY.test(noteThresholdValue)) {
469	      this.settingsError.set('Type a note threshold of 0.00 or more, with up to two decimals, or leave it blank for none.');
470	      return;
471	    }
472	    if (changed(graceDays) && graceDaysValue !== '' && (!DAYS.test(graceDaysValue) || Number(graceDaysValue) > 36500)) {
473	      this.settingsError.set('Type grace days as a whole number of business days, from 0 to 36500, or leave them blank for off.');
474	      return;
475	    }
476	    if (changed(entryDate) && entryDateValue !== '' && !isDate(entryDateValue)) {
477	      this.settingsError.set('Type an entry date as yyyy-mm-dd, or leave it blank for the sheet\'s today.');
478	      return;
479	    }
480	    if (changed(pot) && potValue !== '' && !MONEY.test(potValue)) {
481	      this.settingsError.set('Type a pot of 0.00 or more, with up to two decimals, or leave it blank for none.');
482	      return;
483	    }
484	    const permissionValues = PERMISSION_ACTIONS.map((a) => ({ action: a, control: this.permissionsForm.controls[a],
485	      value: this.permissionsForm.controls[a].value.split(',').map((r) => r.trim()).join(',') }));
486	    for (const { action, control, value } of permissionValues) {
487	      if (changed(control) && value !== '' && !value.split(',').every((r) => ROLES.includes(r as Role))) {
488	        this.settingsError.set(`Name who may ${action} as a comma separated list of clerk, steward and viewer, or leave it blank for the standing rule.`);
489	        return;
490	      }
491	    }
492	    this.savingSettings.set(true);
493	    try {
494	      if (dirty(clerkLimit, clerkLimitFrom)) {
495	        const settings = await this.api.setClerkLimit(sheet.id, limit === '' ? null : limit, fromOf(clerkLimitFrom));
496	        settled(clerkLimit);
497	        settled(clerkLimitFrom);
498	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
499	      }
500	      if (dirty(floor, floorFrom)) {
501	        const settings = await this.api.setFloor(sheet.id, floorValue, fromOf(floorFrom));
502	        settled(floor);
503	        settled(floorFrom);
504	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
505	      }
506	      if (dirty(terms, termsFrom)) {
507	        const settings = await this.api.setTerms(sheet.id, Number(termsValue), fromOf(termsFrom));
508	        settled(terms);
509	        settled(termsFrom);
510	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
511	      }
512	      for (const { grade, control, from, value } of gradeTermsValues) {
513	        if (!dirty(control, from)) continue;
514	        const settings = await this.api.setGradeTerms(sheet.id, grade, value === '' ? null : Number(value), fromOf(from));
515	        settled(control);
516	        settled(from);
517	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
518	      }
519	      if (dirty(latePct, latePctFrom)) {
520	        const settings = await this.api.setLatePct(sheet.id, latePctValue, fromOf(latePctFrom));
521	        settled(latePct);
522	        settled(latePctFrom);
523	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
524	      }
525	      for (const { grade, control, from, value } of gradeGraceValues) {
526	        if (!dirty(control, from)) continue;
527	        const settings = await this.api.setGradeGrace(sheet.id, grade, value === '' ? null : Number(value), fromOf(from));
528	        settled(control);
529	        settled(from);
530	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
531	      }
532	      if (changed(policyDate)) {
533	        const settings = await this.api.setPolicyDate(sheet.id, policyDateValue === '' ? null : policyDateValue);
534	        settled(policyDate);
535	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
536	      }
537	      if (changed(periodNumberingFrom)) {
538	        const settings = await this.api.setPeriodNumberingFrom(sheet.id, periodNumberingFromValue === '' ? null : periodNumberingFromValue);
539	        settled(periodNumberingFrom);
540	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
541	      }
542	      if (dirty(cap, capFrom)) {
543	        const settings = await this.api.setCap(sheet.id, capValue === '' ? null : capValue, fromOf(capFrom));
544	        settled(cap);
545	        settled(capFrom);
546	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
547	      }
548	      if (dirty(proofThreshold, proofThresholdFrom)) {
549	        const settings = await this.api.setProofThreshold(sheet.id, proofThresholdValue === '' ? null : proofThresholdValue,
550	          fromOf(proofThresholdFrom));
551	        settled(proofThreshold);
552	        settled(proofThresholdFrom);
553	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
554	      }
555	      for (const { grade, control, from, value } of gradeProofThresholdValues) {
556	        if (!dirty(control, from)) continue;
557	        const settings = await this.api.setGradeProofThreshold(sheet.id, grade, value === '' ? null : value, fromOf(from));
558	        settled(control);
559	        settled(from);
560	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
561	      }
562	      if (dirty(noteThreshold, noteThresholdFrom)) {
563	        const settings = await this.api.setNoteThreshold(sheet.id, noteThresholdValue === '' ? null : noteThresholdValue,
564	          fromOf(noteThresholdFrom));
565	        settled(noteThreshold);
566	        settled(noteThresholdFrom);
567	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
568	      }
569	      if (changed(graceDays)) {
570	        const settings = await this.api.setGraceDays(sheet.id, graceDaysValue === '' ? null : Number(graceDaysValue));
571	        settled(graceDays);
572	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
573	      }
574	      if (changed(entryDate)) {
575	        const settings = await this.api.setEntryDate(sheet.id, entryDateValue === '' ? null : entryDateValue);
576	        settled(entryDate);
577	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
578	      }
579	      if (changed(pot)) {
580	        const settings = await this.api.setPot(sheet.id, potValue === '' ? null : potValue);
581	        settled(pot);
582	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
583	      }
584	      for (const { action, control, value } of permissionValues) {
585	        if (!changed(control)) continue;
586	        const settings = await this.api.setPermission(sheet.id, action, value);
587	        settled(control);
588	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
589	      }
590	    } catch {
591	      this.settingsError.set('The settings could not be saved.');
592	    } finally {
593	      this.savingSettings.set(false);
594	    }
