597	  /** The terms in force for a grade on the sheet's today: its own, else the sheet's. */
598	  protected gradeTermsNow(grade: Grade): number {
599	    const own = this.now(`terms-${grade}`);
600	    return own === null ? this.terms() : Number(own);
601	  }
602	
603	  /** Show the settings as the store answered them, and share the dated floor, late percent, cap and grades' grace, and
604	   *  the policy date and the pot, with the screens showing them. */
605	  private show(settings: SettingsView): void {
606	    this.dated.set(settings.dated);
607	    this.sheetFloor.history.set(settings.dated['floor'] ?? []);
608	    this.sheetLatePct.history.set(settings.dated['late-pct'] ?? []);
609	    this.sheetCap.history.set(settings.dated['cap'] ?? []);
610	    this.sheetGrace.history.set(Object.fromEntries(GRADES.map((g) => [g, settings.dated[`grace-${g}`] ?? []])));
611	    this.policyDate.set(settings.policyDate);
612	    this.sheetPolicyDate.date.set(settings.policyDate);
613	    this.periodNumberingFrom.set(settings.periodNumberingFrom);
614	    this.assigned.set(settings.roles);
615	    this.permissions.set(settings.permissions);
616	    this.graceDays.set(settings.graceDays);
617	    this.entryDate.set(settings.entryDate);
618	    this.pot.set(settings.pot);
619	    this.sheetPot.pot.set(settings.pot);
620	    this.delegations.set(settings.delegations);
621	  }
622	
623	  protected async saveRole(): Promise<void> {
624	    if (this.savingRole()) return;
625	    const sheet = this.session.sheet();
626	    if (!sheet) return;
627	    this.roleError.set('');
628	    const user = this.roleForm.getRawValue().user.trim();
629	    const role = this.roleForm.getRawValue().role.trim();
630	    if (user === '') {
631	      this.roleError.set('Type the user name to assign a role to.');
632	      return;
633	    }
634	    if (!ROLES.includes(role as Role)) {
635	      this.roleError.set('Choose a role of clerk, steward or viewer.');
636	      return;
637	    }
638	    this.savingRole.set(true);
639	    try {
640	      const saved = await this.api.setRole(sheet.id, user, role as Role);
641	      if (this.session.sheet()?.id === sheet.id) {
642	        this.assigned.update((list) =>
643	          [...list.filter((r) => r.user !== saved.user), saved].sort((a, b) => (a.user < b.user ? -1 : a.user > b.user ? 1 : 0)));
644	      }
645	    } catch {
646	      this.roleError.set('The role could not be assigned.');
647	    } finally {
648	      this.savingRole.set(false);
649	    }
650	  }
651	
652	  protected async saveDelegation(): Promise<void> {
653	    if (this.savingDelegation()) return;
654	    const sheet = this.session.sheet();
655	    if (!sheet) return;
656	    this.delegateError.set('');
657	    const { user, from, to } = this.delegateForm.getRawValue();
658	    const name = user.trim();
659	    const start = from.trim();
660	    const end = to.trim();
661	    if (name === '') {
662	      this.delegateError.set('Type the user name to delegate the steward role to.');
663	      return;
664	    }
665	    if ((start !== '' && !isDate(start)) || !isDate(end)) {
666	      this.delegateError.set('Type the dates as yyyy-mm-dd.');
667	      return;
668	    }
669	    if (end < (start === '' ? sheet.today : start)) {
670	      this.delegateError.set('The to-date cannot be before the from-date.');
671	      return;
672	    }
673	    this.savingDelegation.set(true);
674	    try {
675	      const saved = await this.api.delegate(sheet.id, name, start === '' ? null : start, end);
676	      if (this.session.sheet()?.id === sheet.id) this.delegations.update((list) => [...list, saved]);
677	    } catch {
678	      this.delegateError.set('Only a steward can delegate the steward role.');
679	    } finally {
680	      this.savingDelegation.set(false);
681	    }
682	  }
683	}
