    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SheetSettingRepository settings;
    private final SheetSettingDatedRepository dated;
    private final Audit audit;

    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SheetSettingRepository settings, SheetSettingDatedRepository dated, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
        this.dated = dated;
        this.audit = audit;
    }

    /** The sheet's figures as the store holds them now, within the caller's transaction. */
    public Snapshot snapshot(String sheetId) {
        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
        // The floor and late percent are those in force on each claim's date; the cap that in force today.
        DatedSettings values = DatedSettings.of(dated, sheetId);
        BigDecimal cap = values.capOn(today);
        LocalDate policyDate = Rounding.policyDate(SettingService.policyDateOf(settings, sheetId), today);
        Map<Grade, List<Rate>> ratesByGrade = new LinkedHashMap<>();
        for (Rate rate : rates.findBySheetIdInOrder(sheetId)) {
            ratesByGrade.computeIfAbsent(rate.getGrade(), g -> new ArrayList<>()).add(rate);
        }
        Map<Long, List<Claim>> claimsByPerson = new LinkedHashMap<>();
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            claimsByPerson.computeIfAbsent(claim.getPersonId(), p -> new ArrayList<>()).add(claim);
        }
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = ZERO;
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            Grade gradeToday = today == null ? null : person.gradeOn(today);
            BigDecimal claimed = ZERO;
            BigDecimal due = ZERO;
            BigDecimal overdue = ZERO;
            boolean keptFigure = false;
            List<Claim> theirs = claimsByPerson.getOrDefault(person.getId(), List.of());
            for (Claim claim : theirs) {
                if (!counts(person, claim, today)) continue;
                claimed = claimed.add(claim.getAmount());
                // A claim's live figure is at the grade in force on its date.
                Grade grade = person.gradeOn(claim.getDate());
                RoundingMode rounding = Rounding.of(Rounding.dateOf(claim, corrected(claim, theirs)), policyDate);
                BigDecimal figure = figure(claim, ratesByGrade.getOrDefault(grade, List.of()), rounding);
                int grace = values.graceOn(grade, claim.getDate());
                BigDecimal owed = LateCharge.dueOf(claim, figure, values.floorOn(claim.getDate()), today,
                        grace, values::latePctOn, rounding);
                if (owed != null) due = due.add(owed);
                if (owed != null && isOverdue(claim, grace, today)) overdue = overdue.add(owed);
                if (claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)) {
                    keptFigure = true;
                }
                // A live figure at a grade other than today's is not undone by today's grade having no rate.
                if (figure != null && grade != gradeToday) keptFigure = true;
                // Nor is a live figure on a claim dated by today undone by its rate having ended since.
                if (figure != null && today != null && !claim.getDate().isAfter(today)) keptFigure = true;
            }
            // n/a when no rate of the grade in force today is in force today and no claim keeps a figure.
            // Held to the sheet's cap; n/a is not capped.
            BigDecimal personDue = SettingService.capped((today == null
                    || Rate.inForce(ratesByGrade.getOrDefault(gradeToday, List.of()), today) == null) && !keptFigure
                            ? null : due, cap);
            figures.put(person.getId(), new Figures(person.getName(), claimed, personDue, overdue));
            claimedTotal = claimedTotal.add(claimed);
            if (personDue != null) dues.add(personDue);
            overdues.add(overdue);
        }
        return new Snapshot(sheetId, figures, claimedTotal, trimmedSum(dues), trimmedSum(overdues));
    }

    /** Audit, once the transaction commits, each person's due-total as it stood in the snapshot, in the
     *  order they were added. */
    public void recordSnapshot(String user, Snapshot before) {
        String prefix = " sheet=" + before.sheetId() + " by=" + user;
        before.people().values().forEach(figures -> audit.recordOnCommit("SNAPSHOT" + prefix + " name="
                + figures.name() + " due-total=" + text(figures.dueTotal())));
    }

    /** Audit, once the transaction commits, the figures that moved since the snapshot was taken. */
    public void recordChanges(String user, Snapshot before) {
        Snapshot after = snapshot(before.sheetId());
        String prefix = " sheet=" + before.sheetId() + " by=" + user;
        after.people().forEach((id, now) -> {
            if (!now.sameAs(before.people().get(id))) {
                audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + text(now.claimed())
                        + " due-total=" + text(now.dueTotal()) + " overdue-total=" + text(now.overdueTotal()));
            }
        });
        if (!same(before.claimedTotal(), after.claimedTotal()) || !same(before.dueTotal(), after.dueTotal())
                || !same(before.overdueTotal(), after.overdueTotal())) {
            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + text(after.claimedTotal())
                    + " due-total=" + text(after.dueTotal()) + " overdue-total=" + text(after.overdueTotal()));
        }
    }

    /** Whether the claim is overdue: open and not deferred, with its due-by plus the grace days of its
     *  person's grade before the sheet's today. */
    private static boolean isOverdue(Claim claim, int grace, LocalDate today) {
        return claim.getStatus().isOpen() && !claim.isDeferredOn(today) && today != null
                && LateCharge.lateFrom(claim, grace).isBefore(today);
    }

    /** Only open (PENDING included) and settled claims count toward what is claimed and due; a person's
     *  open claims dated within one of their holds, or all of them once their retirement date is reached,
     *  do not, unless a statement binds them; nor does a
     *  claim deferred on the sheet's today. */
    private static boolean counts(Person person, Claim claim, LocalDate today) {
        return claim.getStatus() == ClaimStatus.SETTLED
                || (claim.getStatus().isOpen() && !claim.isDeferredOn(today)
                        && (claim.isBound() || !person.isLeftOut(claim.getDate(), today)));
    }

    /** The claim's figure, as ClaimService.figure works it out: the settled due, else the stated due,
     *  (unless PENDING), else the rate figure at the grade's rate in force on its date, rounded as the claim rounds,
     *  before any late charge and floor; null when that is n/a. */
    private static BigDecimal figure(Claim claim, List<Rate> gradeRates, RoundingMode rounding) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        if (claim.isBound()) return claim.getStatedDue();
        Rate rate = Rate.inForce(gradeRates, claim.getDate());
        if (rate == null) return null;
        return claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2, rounding);
    }

    /** Of the person's claims, the one a correction corrects by number; null for any other claim. */
    private static Claim corrected(Claim claim, List<Claim> theirs) {
        if (!claim.isCorrection() || claim.getCorrects() == null) return null;
        for (Claim other : theirs) {
            if (claim.getCorrects().equals(other.getNumber())) return other;
        }
        return null;
    }

    /** The sum of the figures, leaving out the single highest and the single lowest when there are three or more. */
    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
        BigDecimal total = figures.stream().reduce(ZERO, BigDecimal::add);
        if (figures.size() < 3) return total;
        return total.subtract(figures.stream().max(BigDecimal::compareTo).get())
                .subtract(figures.stream().min(BigDecimal::compareTo).get());
    }

    private static boolean same(BigDecimal a, BigDecimal b) {
        return a == null || b == null ? Objects.equals(a, b) : a.compareTo(b) == 0;
    }

    private static String text(BigDecimal figure) {
        return figure == null ? "n/a" : figure.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Grade } from '../people/people-api';

export interface RateView {
  grade: Grade;
  /** The percent with two decimals, as the store holds it. */
  pct: string;
  /** The date the rate is in force from (yyyy-mm-dd), or null when it applies from the beginning of time. */
  from: string | null;
  /** The last date the rate is in force (yyyy-mm-dd), or null when it runs until the grade's next rate. */
  to: string | null;
}

/** Of one grade's rates, the one in force on a date: the one with the latest from-date on or before
 *  it, or null when the date is before every one of them or after that one's to-date. */
export function rateInForce(rates: readonly RateView[], date: string): RateView | null {
  let inForce: RateView | null = null;
  for (const r of rates) {
    if (r.from !== null && r.from > date) continue;
    if (inForce === null || (inForce.from ?? '') < (r.from ?? '')) inForce = r;
  }
  return inForce !== null && inForce.to !== null && inForce.to < date ? null : inForce;
}

/** Whether two rates are the same grade's rate for the same from-date. */
export function sameRate(a: RateView, b: RateView): boolean {
  return a.grade === b.grade && a.from === b.from;
}

/** What is due on an amount of `amountCents` at a rate of `pct` percent, in whole cents: the
 *  amount times the rate, divided by 100, rounded half to even (a half rounds to the even cent), or
 *  half up (a half rounds away from zero) when `halfUp`. */
export function dueCents(amountCents: number, pct: string, halfUp = false): number {
  // Hundredths of a percent, so the product is exact; cents x basis points / 10000 = due cents.
  const product = BigInt(amountCents) * BigInt(Math.round(Number(pct) * 100));
  const sign = product < 0n ? -1n : 1n;
  const magnitude = sign * product;
  let whole = magnitude / 10000n;
  const rest = magnitude % 10000n;
  if (rest > 5000n || (rest === 5000n && (halfUp || whole % 2n === 1n))) whole += 1n;
  return Number(whole * sign);
}

/** What a candidate rate would do: how many claims would show a different due, and the sum of the
 *  differences (new due less current due) with two decimals. */
export interface RatePreview {
  count: number;
  diff: string;
}

// The sheet's rates per grade, as the store holds them.
@Injectable({ providedIn: 'root' })
export class RatesApi {
  private readonly http = inject(HttpClient);

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/rates`;
  }

  /** The sheet's rates; a grade with no rate is left out. */
  list(sheetId: string): Promise<RateView[]> {
    return firstValueFrom(this.http.get<RateView[]>(this.url(sheetId)));
  }

  /** Set the grade's rate from a from-date (null: from the beginning of time) through a to-date
   *  (null: until the grade's next rate), replacing the one it had for that from-date. */
  set(sheetId: string, grade: Grade, pct: string, from: string | null, to: string | null): Promise<RateView> {
    return firstValueFrom(this.http.put<RateView>(`${this.url(sheetId)}/${grade}`, { pct, from, to }));
  }

  /** Preview the grade's candidate percent on every date; nothing is saved. */
  preview(sheetId: string, grade: Grade, pct: string): Promise<RatePreview> {
    return firstValueFrom(this.http.get<RatePreview>(`${this.url(sheetId)}/${grade}/preview`, { params: { pct } }));
  }
}
import { Component, computed, effect, inject, input, output, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';
import { GRADES, Grade } from '../people/people-api';
import { RatePreview, RateView, RatesApi, rateInForce } from './rates-api';

const PCT = /^\d{1,3}(\.\d{1,2})?$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;

// The sheet's rate in force today for each grade, and every rate with its from-date and to-date,
// with one form to set a grade's rate from a from-date through a to-date.
@Component({
  selector: 'app-rates',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="rates-heading">
      <h2 id="rates-heading">Rates</h2>
      <form [formGroup]="form" (ngSubmit)="submit()" aria-label="Set a rate">
        <label for="rate-form-grade">Grade</label>
        <select id="rate-form-grade" data-testid="rate-form-grade" formControlName="grade">
          @for (g of grades; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <label for="rate-form-pct">Rate (%)</label>
        <input id="rate-form-pct" data-testid="rate-form-pct" formControlName="pct" inputmode="decimal" />
        <label for="rate-form-from">From (blank: from the start)</label>
        <input id="rate-form-from" type="date" data-testid="rate-form-from" formControlName="from" />
        <label for="rate-form-to">To (blank: until the next rate)</label>
        <input id="rate-form-to" type="date" data-testid="rate-form-to" formControlName="to" />
        <button type="submit" data-testid="rate-form-submit" [disabled]="saving()">Set rate</button>
        @if (error()) {
          <p role="alert" data-testid="rate-form-error">{{ error() }}</p>
        }
      </form>
      <form [formGroup]="previewForm" (ngSubmit)="preview()" aria-label="Preview a rate">
        <label for="rate-preview-grade">Grade</label>
        <select id="rate-preview-grade" data-testid="rate-preview-grade" formControlName="grade">
          @for (g of grades; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <label for="rate-preview-pct">Candidate rate (%)</label>
        <input id="rate-preview-pct" data-testid="rate-preview-pct" formControlName="pct" inputmode="decimal" />
        <button type="submit" data-testid="rate-preview" [disabled]="previewing()">Preview</button>
        @if (previewError()) {
          <p role="alert" data-testid="rate-preview-error">{{ previewError() }}</p>
        }
        @if (previewed(); as p) {
          <p aria-live="polite">
            Claims that would change: <span data-testid="rate-preview-count">{{ p.count }}</span>;
            difference in due: <span data-testid="rate-preview-diff">{{ p.diff }}</span>
          </p>
        }
      </form>
      <table aria-label="Rates in force today">
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">Rate today (%)</th></tr>
        </thead>
        <tbody>
          @for (g of grades; track g) {
            <tr>
              <th scope="row">{{ g }}</th>
              <td [attr.data-testid]="'rate-current-' + g">{{ currentOf(g) }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table data-testid="rates-list" aria-label="All rates">
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">From</th><th scope="col">To</th><th scope="col">Rate (%)</th></tr>
        </thead>
        <tbody>
          @for (r of rates(); track r.grade + (r.from ?? 'start')) {
            <tr [attr.data-testid]="'rate-row-' + r.grade + '-' + (r.from ?? 'start')">
              <th scope="row">{{ r.grade }}</th>
              <td data-testid="rate-from">{{ r.from ?? 'start' }}</td>
              <td data-testid="rate-to">{{ r.to ?? '' }}</td>
              <td data-testid="rate-pct">{{ r.pct }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class Rates {
  private readonly session = inject(Session);
  private readonly api = inject(RatesApi);

  /** The sheet's rates, in grade order then by from-date; a grade with no rate is left out. */
  readonly rates = input.required<RateView[]>();
  readonly saved = output<RateView>();

  protected readonly grades = GRADES;
  protected readonly grade = new FormControl<Grade>('A', { nonNullable: true });
  protected readonly pct = new FormControl('', { nonNullable: true });
  protected readonly from = new FormControl('', { nonNullable: true });
  protected readonly to = new FormControl('', { nonNullable: true });
  protected readonly form = new FormGroup({ grade: this.grade, pct: this.pct, from: this.from, to: this.to });
  protected readonly saving = signal(false);
  protected readonly error = signal('');
  protected readonly previewGrade = new FormControl<Grade>('A', { nonNullable: true });
  protected readonly previewPct = new FormControl('', { nonNullable: true });
  protected readonly previewForm = new FormGroup({ grade: this.previewGrade, pct: this.previewPct });
  protected readonly previewing = signal(false);
  protected readonly previewError = signal('');
  protected readonly previewed = signal<RatePreview | null>(null);

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
    this.previewForm.valueChanges.subscribe(() => this.previewError.set(''));
    // Each load of a sheet starts the forms without the error or preview from the last one.
    effect(() => {
      this.session.loaded();
      this.error.set('');
      this.previewError.set('');
      this.previewed.set(null);
    });
  }

  private readonly today = computed(() => this.session.sheet()?.today ?? null);

  /** The grade's rate in force on the sheet's today, or n/a when none is. */
  protected currentOf(grade: Grade): string {
    const today = this.today();
    const rate = today === null ? null : rateInForce(this.rates().filter((r) => r.grade === grade), today);
    return rate?.pct ?? 'n/a';
  }

  protected async submit(): Promise<void> {
    // A second submit before the first has answered is ignored, so it stores one record, not two.
    if (this.saving()) return;
    const sheet = this.session.sheet();
    if (!sheet) return;
    this.error.set('');
    const { grade, pct, from, to } = this.form.getRawValue();
    if (!GRADES.includes(grade)) {
      this.error.set('Choose a grade of A, B or C.');
      return;
    }
    if (!PCT.test(pct.trim())) {
      this.error.set('Type a rate of 0.00 or more, with up to two decimals.');
      return;
    }
    if (from.trim() !== '' && !DATE.test(from.trim())) {
      this.error.set('Type a from-date as yyyy-mm-dd, or leave it blank.');
      return;
    }
    if (to.trim() !== '' && !DATE.test(to.trim())) {
      this.error.set('Type a to-date as yyyy-mm-dd, or leave it blank.');
      return;
    }
    if (from.trim() !== '' && to.trim() !== '' && to.trim() < from.trim()) {
      this.error.set('The to-date cannot be before the from-date.');
      return;
    }
    this.saving.set(true);
    try {
      const rate = await this.api.set(sheet.id, grade, pct.trim(), from.trim() === '' ? null : from.trim(),
        to.trim() === '' ? null : to.trim());
      if (this.session.sheet()?.id === sheet.id) this.saved.emit(rate);
    } catch {
      this.error.set('The rate could not be set.');
    } finally {
      this.saving.set(false);
    }
  }

  /** Show what the candidate rate would do to the grade's open claims; nothing is saved. The last
   *  result is cleared while the preview runs, so two equal results are still told apart. */
  protected async preview(): Promise<void> {
    if (this.previewing()) return;
    const sheet = this.session.sheet();
    if (!sheet) return;
    this.previewError.set('');
    this.previewed.set(null);
    const { grade, pct } = this.previewForm.getRawValue();
    if (!GRADES.includes(grade)) {
      this.previewError.set('Choose a grade of A, B or C.');
      return;
    }
    if (!PCT.test(pct.trim())) {
      this.previewError.set('Type a rate of 0.00 or more, with up to two decimals.');
      return;
    }
    this.previewing.set(true);
    try {
      const result = await this.api.preview(sheet.id, grade, pct.trim());
      if (this.session.sheet()?.id === sheet.id) this.previewed.set(result);
    } catch {
      this.previewError.set('The rate could not be previewed.');
    } finally {
      this.previewing.set(false);
    }
  }
}

