            if (parent.isEmpty() || parent.get(0).equals(sheet) || parents.contains(parent.get(0))) break;
            at = parent.get(0);
            parents.add(at);
        }
        restore(sheet, asOf);
        for (String parent : parents) restore(parent, asOf);
    }

